  function staleRequest(){return Object.assign(new Error("This request belonged to a previous sign-in."),{stale:true});}
  function signOutLocal(){app.epoch++;app.slackTicket=null;app.slackSetup=null;clearInterval(app.poll);clearTimeout(app.draftTimer);clearTimeout(app.filterTimer);clearTimeout(app.scrollTimer);app.poll=null;app.session={authenticated:false,owner:app.session?.owner};app.csrf="";app.config=null;app.status=null;app.view=null;app.pending.clear();app.tokenOnce=null;app.lastAck=0;app.remoteFocus=null;app.remoteScroll=null;render();}
  function acceptView(v,remote=false){if(app.view?.id===v.id&&v.revision<app.view.revision)return;const old=app.view?.state;if(remote){if(v.state.focus!==old?.focus)app.remoteFocus=v.state.focus;if(JSON.stringify(v.state.scroll)!==JSON.stringify(old?.scroll))app.remoteScroll=v.state.scroll;if(v.state.modal!==old?.modal&&v.state.modal===null)app.tokenOnce=null;}app.view=v;}
  function commands(commandList,{redraw=true}={}){const epoch=app.epoch;const task=async()=>{if(epoch!==app.epoch)throw staleRequest();if(!app.view)throw new Error("This display is not connected yet.");app.commanding++;try{let value,conflicted=false;for(let attempt=0;attempt<2;attempt++){try{value=await api(`views/${encodeURIComponent(app.view.id)}/commands`,{method:"POST",body:{expected_revision:app.view.revision,commands:commandList}});break;}catch(e){if(e.status!==409||attempt)throw e;conflicted=true;acceptView(await api(`views/${encodeURIComponent(app.view.id)}`),true);}}acceptView(value,conflicted);if(redraw||conflicted)render();else{const el=document.querySelector("[data-view-revision]");if(el)el.textContent=app.view.revision;ack();}return clone(value);}finally{app.commanding--;}};const result=app.queue.then(task,task);app.queue=result.catch(()=>{});return result;}
