  function buildConfig(){const c=clone(app.config),spec={"label":"string","participation":"string","slack.allow_dms":"bool","slack.channels":"array","context.enabled":"bool","context.thread_only_grants":"bool","context.owner_slack_user_id":"string","media.incoming":"bool","media.outgoing":"bool","media.max_files":"number","media.max_file_bytes":"number","acp.command":"string","acp.args":"array","acp.env":"object","acp.secret_env":"object","acp.cwd":"string","acp.timeout_seconds":"number","server.bind":"string","server.port":"number","server.public_url":"nullable","server.embed_origins":"array"};for(const [k,v] of Object.entries(c.acp.client||{}))spec[`acp.client.${k}`]=Array.isArray(v)?"array":typeof v==="boolean"?"bool":"number";for(const k of Object.keys(c.attention||{}))if(typeof c.attention[k]==="number")spec[`attention.${k}`]="number";for(const [path,type]of Object.entries(spec)){let value=draft(`config.${path}`,get(c,path));if(type==="array"||type==="object"){if(typeof value==="string"){try{value=JSON.parse(value);}catch{throw new Error(`${title(path)} must contain valid JSON.`);}}if(type==="array"?!Array.isArray(value):!value||Array.isArray(value)||typeof value!=="object")throw new Error(`${title(path)} must be a JSON ${type}.`);}else if(type==="number"){value=Number(value);if(!Number.isSafeInteger(value)||value<0)throw new Error(`${title(path)} must be a positive whole number.`);}else if(type==="nullable")value=String(value??"").trim()||null;else if(type==="bool")value=!!value;else value=String(value??"").trim();put(c,path,value);}const channels=draft("channels_text",null);if(channels!==null)c.slack.channels=String(channels).split(/[\s,]+/).map(v=>v.trim()).filter(Boolean);return c;}
  async function saveConfig(show=true){await flushDrafts();const candidate=buildConfig();if(JSON.stringify(candidate)!==JSON.stringify(app.config))app.config=await api("config",{method:"PUT",body:{expected_revision:app.config.revision,config:candidate}});await commands([{type:"set_draft",path:"config",value:{}},{type:"set_draft",path:"channels_text",value:null}],{redraw:false});app.checks=null;await refresh(false);if(show)notice("Connection settings saved.");}
