  async function connectSetup(details){
    if(app.config.setup_complete)throw new Error("This connection is already set up. Use Connection settings to make changes.");
    await saveConfig(false);
    if(!app.config.acp.command)throw new Error("Choose an agent connection in Advanced settings before connecting to Slack.");
    let verified=false,imageError=false;
    if(details.app_token||details.bot_token){
      if(!details.app_token||!details.bot_token)throw new Error("Both connection keys are needed. Copy the receive and reply keys from the same Slack app.");
      await api("credentials/slack",{method:"POST",body:{app_token:details.app_token,bot_token:details.bot_token}});
      for(const field of root.querySelectorAll('#setup-connect-form [name="app_token"], #setup-connect-form [name="bot_token"]'))field.value="";
      app.config=await api("config");await refresh(false);verified=true;
    }else if(!app.status?.credentials?.slack)throw new Error("Copy the two connection keys from Slack first.");
    if(details.image_token){
      try{app.status.portrait=await api("identity/credential",{method:"PUT",body:{token:details.image_token,refresh_token:details.image_refresh_token||""}});for(const field of root.querySelectorAll('#setup-connect-form [name^="image_"]'))field.value="";}
      catch(e){if(e.stale||e.status===401)throw e;imageError=true;}
    }
    await finishSetup(verified);
    return notice(imageError?"Connected to Slack. Image access wasn’t saved; you can reconnect it in Connection settings.":"Connected. Open Slack and invite your agent into a conversation. Image updates start automatically if enabled.");
  }
