  function input(e){const el=e.target;if(el.hasAttribute("data-sensitive"))return;if(el.dataset.draft){if(el.type==="radio"&&!el.checked)return;app.pending.set(el.dataset.draft,el.type==="checkbox"?el.checked:el.value);clearTimeout(app.draftTimer);app.draftTimer=setTimeout(()=>flushDrafts().catch(fail),250);}if(el.dataset.filter){clearTimeout(app.filterTimer);const value=el.type==="checkbox"?el.checked:el.value;app.filterTimer=setTimeout(()=>commands([{type:"set_filter",key:el.dataset.filter,value}]).catch(fail),180);}}
